/* ChartPulse Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #0F0F0F;
  --bg-secondary: #1a1a2e;
  --bg-card: #16162a;
  --bg-elevated: #1e1e3a;
  --bg-input: #12122a;
  --border: #2a2a4a;
  --border-light: #333366;
  --text-primary: #e8e8f0;
  --text-secondary: #9898b8;
  --text-muted: #6868a0;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e50d4;
  --accent-green: #26a69a;
  --accent-green-bright: #00e676;
  --accent-red: #F7525F;
  --accent-red-dark: #d32f2f;
  --accent-gold: #FFD700;
  --accent-teal: #00bcd4;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --radius: 8px;
  --radius-sm: 4px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 4px 20px rgba(0,0,0,0.5);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-teal); }

img { max-width: 100%; display: block; }

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(15, 15, 15, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
}

.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 56px;
  gap: 32px;
}

.nav-logo {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.nav-logo svg { flex-shrink: 0; }

.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
  flex: 1;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-search {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 7px 14px;
  color: var(--text-primary);
  font-size: 13px;
  width: 200px;
  outline: none;
  transition: border-color var(--transition);
}

.nav-search::placeholder { color: var(--text-muted); }
.nav-search:focus { border-color: var(--accent-blue); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 18px;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
  font-family: var(--font);
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
}
.btn-primary:hover { background: var(--accent-blue-hover); transform: translateY(-1px); }

.btn-secondary {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
}
.btn-secondary:hover { color: var(--text-primary); border-color: var(--text-muted); }

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 6px 12px;
}
.btn-ghost:hover { color: var(--text-primary); }

/* Container */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Market Ticker Bar */
.ticker-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 8px 0;
  overflow: hidden;
}

.ticker-bar-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 24px;
  overflow-x: auto;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
  font-size: 12px;
  flex-shrink: 0;
}

.ticker-name { color: var(--text-secondary); font-weight: 500; }
.ticker-price { color: var(--text-primary); font-weight: 600; }
.ticker-change { font-weight: 600; font-size: 11px; }

/* Change colors */
.positive { color: var(--accent-green-bright); }
.negative { color: var(--accent-red); }
.neutral { color: var(--text-muted); }

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
}

.badge-green { background: rgba(0, 230, 118, 0.12); color: var(--accent-green-bright); }
.badge-red { background: rgba(247, 82, 95, 0.12); color: var(--accent-red); }
.badge-blue { background: rgba(41, 98, 255, 0.12); color: var(--accent-blue); }
.badge-gold { background: rgba(255, 215, 0, 0.12); color: var(--accent-gold); }

/* Section Headers */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  gap: 16px;
}

.section-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-primary);
}

.section-subtitle {
  font-size: 13px;
  color: var(--text-secondary);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--bg-input);
  border-radius: var(--radius);
  padding: 3px;
  overflow-x: auto;
}

.tab {
  padding: 6px 16px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  background: none;
  white-space: nowrap;
  font-family: var(--font);
}

.tab:hover { color: var(--text-secondary); }
.tab.active { background: var(--accent-blue); color: white; }

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  transition: border-color var(--transition);
}

.card:hover { border-color: var(--border-light); }

/* Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
}

.data-table td {
  padding: 10px 12px;
  font-size: 13px;
  border-bottom: 1px solid rgba(42, 42, 74, 0.4);
}

.data-table tr:hover td { background: rgba(41, 98, 255, 0.04); }

.data-table .text-right { text-align: right; }
.data-table .text-mono { font-variant-numeric: tabular-nums; }

/* Sparkline SVG */
.sparkline {
  width: 80px;
  height: 30px;
}

.sparkline-up { stroke: var(--accent-green-bright); }
.sparkline-down { stroke: var(--accent-red); }

/* Grid layouts */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* Responsive grids */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-4, .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .nav-search { width: 140px; }
  .container { padding: 0 16px; }
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 48px 0 24px;
  margin-top: 60px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 24px;
  margin-bottom: 32px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 12px;
}

.footer-col a {
  display: block;
  font-size: 12px;
  color: var(--text-muted);
  padding: 3px 0;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text-muted);
}

@media (max-width: 768px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

/* Hero Section */
.hero {
  padding: 80px 0 60px;
  text-align: center;
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
}

.hero h1 {
  font-size: 48px;
  font-weight: 800;
  line-height: 1.15;
  max-width: 720px;
  margin: 0 auto 16px;
  background: linear-gradient(135deg, #e8e8f0, #9898b8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
  line-height: 1.6;
}

.hero-cta {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.hero-cta .btn { padding: 12px 28px; font-size: 15px; }

@media (max-width: 768px) {
  .hero h1 { font-size: 32px; }
  .hero p { font-size: 16px; }
}

/* Stats bar */
.stats-bar {
  display: flex;
  justify-content: center;
  gap: 48px;
  padding: 40px 0;
}

.stat-item { text-align: center; }
.stat-value { font-size: 32px; font-weight: 800; color: var(--text-primary); }
.stat-label { font-size: 13px; color: var(--text-muted); margin-top: 4px; }

/* Idea cards */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}

.idea-card:hover { border-color: var(--accent-blue); transform: translateY(-2px); box-shadow: var(--shadow-lg); }

.idea-card-img {
  height: 160px;
  background: linear-gradient(135deg, var(--bg-elevated), var(--bg-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.idea-card-chart {
  width: 100%;
  height: 100%;
  opacity: 0.6;
}

.idea-card-body { padding: 14px; }

.idea-card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.idea-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--text-muted);
}

.idea-card-meta .author { color: var(--accent-blue); font-weight: 500; }

.idea-card-actions {
  display: flex;
  gap: 12px;
  margin-top: 10px;
  font-size: 11px;
  color: var(--text-muted);
}

.idea-card-actions span {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Broker cards */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  align-items: center;
  gap: 20px;
  transition: all var(--transition);
}

.broker-card:hover { border-color: var(--accent-blue); }

.broker-logo {
  width: 56px;
  height: 56px;
  background: var(--bg-elevated);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 16px;
  color: var(--accent-blue);
  flex-shrink: 0;
}

.broker-info { flex: 1; }

.broker-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.broker-tier {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 10px;
}

.tier-platinum { background: rgba(192, 192, 220, 0.15); color: #c0c0dc; }
.tier-gold { background: rgba(255, 215, 0, 0.15); color: var(--accent-gold); }

.broker-stats {
  display: flex;
  gap: 24px;
  font-size: 12px;
}

.broker-stat-label { color: var(--text-muted); }
.broker-stat-value { font-weight: 600; color: var(--text-primary); }

.broker-rating {
  text-align: center;
  flex-shrink: 0;
}

.broker-rating-value {
  font-size: 24px;
  font-weight: 800;
  color: var(--accent-green-bright);
}

.broker-rating-label {
  font-size: 11px;
  color: var(--text-muted);
}

.broker-promo {
  background: rgba(41, 98, 255, 0.1);
  color: var(--accent-blue);
  font-size: 12px;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  margin-top: 8px;
}

/* Chart page specific */
.chart-layout {
  display: grid;
  grid-template-columns: 280px 1fr 320px;
  height: calc(100vh - 56px);
  overflow: hidden;
}

.chart-sidebar {
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
  flex-wrap: wrap;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 4px;
}

.toolbar-btn {
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  font-family: var(--font);
}

.toolbar-btn:hover { color: var(--text-primary); background: var(--bg-elevated); }
.toolbar-btn.active { color: var(--accent-blue); border-color: var(--accent-blue); background: rgba(41,98,255,0.08); }

.toolbar-divider {
  width: 1px;
  height: 20px;
  background: var(--border);
  margin: 0 4px;
}

.chart-area {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.chart-canvas {
  width: 100%;
  height: 100%;
}

.chart-detail {
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  overflow-y: auto;
  padding: 16px;
}

/* Watchlist */
.watchlist-header {
  padding: 12px 16px;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-group { border-bottom: 1px solid rgba(42, 42, 74, 0.4); }

.watchlist-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  cursor: pointer;
  transition: background var(--transition);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  user-select: none;
  background: none;
  border: none;
  width: 100%;
  font-family: var(--font);
}

.watchlist-group-header:hover { background: rgba(41, 98, 255, 0.04); }

.watchlist-group-header .arrow {
  transition: transform var(--transition);
  color: var(--text-muted);
  font-size: 10px;
}

.watchlist-group.collapsed .arrow { transform: rotate(-90deg); }
.watchlist-group.collapsed .watchlist-items { display: none; }

.watchlist-item {
  display: grid;
  grid-template-columns: 1fr auto auto auto;
  gap: 8px;
  align-items: center;
  padding: 6px 16px;
  font-size: 12px;
  transition: background var(--transition);
  cursor: pointer;
}

.watchlist-item:hover { background: rgba(41, 98, 255, 0.06); }
.watchlist-item.selected { background: rgba(41, 98, 255, 0.1); border-left: 2px solid var(--accent-blue); }

.watchlist-symbol { font-weight: 600; color: var(--text-primary); }
.watchlist-last { font-variant-numeric: tabular-nums; color: var(--text-primary); text-align: right; }
.watchlist-chg { font-variant-numeric: tabular-nums; text-align: right; font-size: 11px; }

/* Detail panel */
.detail-ticker {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.detail-ticker-symbol {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
}

.detail-ticker-exchange {
  font-size: 11px;
  color: var(--text-muted);
  padding: 2px 6px;
  background: var(--bg-elevated);
  border-radius: var(--radius-sm);
}

.detail-company {
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 12px;
}

.detail-price {
  font-size: 32px;
  font-weight: 800;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

.detail-change {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
}

.detail-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 16px;
}

.detail-stat {
  background: var(--bg-card);
  padding: 10px 12px;
}

.detail-stat-label {
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 2px;
}

.detail-stat-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

.detail-headline {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px;
  margin-bottom: 16px;
}

.detail-headline-tag {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-blue);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.detail-headline-text {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.detail-section-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 16px 0 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border);
}

.detail-metric {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 0;
  font-size: 12px;
  border-bottom: 1px solid rgba(42,42,74,0.3);
}

.detail-metric-label { color: var(--text-muted); }
.detail-metric-value { color: var(--text-primary); font-weight: 500; font-variant-numeric: tabular-nums; }

/* Responsive chart layout */
@media (max-width: 1200px) {
  .chart-layout { grid-template-columns: 240px 1fr; }
  .chart-detail { display: none; }
}

@media (max-width: 768px) {
  .chart-layout { grid-template-columns: 1fr; }
  .chart-sidebar { display: none; }
}

/* Market page sections */
.market-section { margin-bottom: 40px; }

.market-section .section-header { margin-bottom: 20px; }

/* Yield curve mini chart */
.yield-chart {
  width: 100%;
  height: 200px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
}

/* Toggle switch */
.toggle {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--border);
  border-radius: 10px;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle.active { background: var(--accent-blue); }

.toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  transition: transform var(--transition);
}

.toggle.active::after { transform: translateX(16px); }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 13px;
  cursor: pointer;
  transition: all var(--transition);
