  --text-secondary: #9898b8;
  --text-muted: #6868a0;
  --accent-blue: #2962FF;
  --accent-blue-hover: #1e50d4;
  --accent-green: #26a69a;
  --accent-green-bright: #00e676;
  --accent-red: #F7525F;
  --accent-red-dark: #d32f2f;
  --accent-gold: #FFD700;
  --accent-teal: #00bcd4;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --radius: 8px;
  --radius-sm: 4px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
